+// Sales from the till. Each dish sold uses one portion of its recipe per
+// unit of `qty`. A ticket is imported once; importing is all or nothing.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** True when a ticket has already been imported. */
+export function hasTicket(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/**
+ * Records sale lines ({ row, ticket, soldAt, dishId, qty }) and consumes their
+ * ingredients with ref `sale:<ticket>`. Lines of tickets already imported are
+ * skipped. Checks every line first; throws (changing nothing) naming the row
+ * where an item runs out. Returns { tickets, dishes } imported.
+ */
+export function recordSales(store, lines) {
+  const fresh = lines.filter((l) => !hasTicket(store, l.ticket));
+  const planned = fresh.map((l) => {
+    const dish = getDish(store, l.dishId);
+    return { ...l, uses: scaled(getRecipe(store, dish.recipeId), l.qty) };
+  });
+  const left = new Map();
+  for (const p of planned) {
+    for (const u of p.uses) {
+      if (!left.has(u.itemId)) left.set(u.itemId, round3(onHand(store, u.itemId)));
+      const available = left.get(u.itemId);
+      if (available < u.qty) {
+        const item = getItem(store, u.itemId);
+        throw new AppError("sale_out_of_stock", { row: p.row, item: item.name, available, unit: item.unit });
+      }
+      left.set(u.itemId, round3(available - u.qty));
+    }
+  }
+  store.data.sales ??= [];
+  for (const p of planned) {
+    for (const u of p.uses) if (u.qty > 0) consume(store, u.itemId, u.qty, { at: p.soldAt, ref: `sale:${p.ticket}` });
+    store.data.sales.push({ id: store.nextId("sale"), ticket: p.ticket, soldAt: p.soldAt, dishId: p.dishId, qty: p.qty, uses: p.uses });
+  }
+  return { tickets: new Set(planned.map((p) => p.ticket)).size, dishes: planned.reduce((s, p) => s + p.qty, 0) };
+}
